PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, display_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'player' CHECK(role IN ('player','super_admin')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invitations (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE, token_hash TEXT NOT NULL UNIQUE, invited_by TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, accepted_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tournaments (id TEXT PRIMARY KEY, title TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'CRC', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ready','live','finalizing','closed','archived')), host_user_id TEXT NOT NULL REFERENCES users(id), created_by TEXT NOT NULL REFERENCES users(id), entry_price_minor INTEGER NOT NULL DEFAULT 10000 CHECK(entry_price_minor>=0), rebuy_price_minor INTEGER NOT NULL DEFAULT 5000 CHECK(rebuy_price_minor>=0), max_rebuys INTEGER NOT NULL DEFAULT 4 CHECK(max_rebuys>=0), host_extra_rebuys INTEGER NOT NULL DEFAULT 1 CHECK(host_extra_rebuys>=0), version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tournament_members (tournament_id TEXT NOT NULL REFERENCES tournaments(id), user_id TEXT NOT NULL REFERENCES users(id), member_role TEXT NOT NULL DEFAULT 'player' CHECK(member_role IN ('player','admin')), player_status TEXT NOT NULL DEFAULT 'registered' CHECK(player_status IN ('registered','active','withdrawn','eliminated')), joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(tournament_id,user_id));
CREATE TABLE prize_rules (tournament_id TEXT NOT NULL REFERENCES tournaments(id), place INTEGER NOT NULL CHECK(place>0), basis_points INTEGER NOT NULL CHECK(basis_points BETWEEN 0 AND 10000), PRIMARY KEY(tournament_id,place));
CREATE TABLE rebuy_requests (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL, user_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled')), requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, decided_at TEXT, decided_by TEXT REFERENCES users(id), FOREIGN KEY(tournament_id,user_id) REFERENCES tournament_members(tournament_id,user_id));
CREATE UNIQUE INDEX one_pending_rebuy_per_player ON rebuy_requests(tournament_id,user_id) WHERE status='pending';
CREATE TABLE entries (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL, user_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('initial','rebuy')), rebuy_request_id TEXT UNIQUE REFERENCES rebuy_requests(id), amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), status TEXT NOT NULL DEFAULT 'valid' CHECK(status IN ('valid','voided')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tournament_id,user_id) REFERENCES tournament_members(tournament_id,user_id), CHECK((kind='initial' AND rebuy_request_id IS NULL) OR (kind='rebuy' AND rebuy_request_id IS NOT NULL)));
CREATE UNIQUE INDEX one_valid_initial_entry ON entries(tournament_id,user_id) WHERE kind='initial' AND status='valid';
CREATE TABLE payments (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL REFERENCES tournaments(id), user_id TEXT NOT NULL REFERENCES users(id), method TEXT NOT NULL CHECK(method IN ('cash','transfer','other')), amount_minor INTEGER NOT NULL CHECK(amount_minor>0), status TEXT NOT NULL DEFAULT 'reported' CHECK(status IN ('reported','confirmed','voided')), reference TEXT, confirmed_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TEXT, FOREIGN KEY(tournament_id,user_id) REFERENCES tournament_members(tournament_id,user_id));
CREATE TABLE payment_allocations (payment_id TEXT NOT NULL REFERENCES payments(id), entry_id TEXT NOT NULL REFERENCES entries(id), amount_minor INTEGER NOT NULL CHECK(amount_minor>0), PRIMARY KEY(payment_id,entry_id));
CREATE TABLE blind_levels (tournament_id TEXT NOT NULL REFERENCES tournaments(id), level_no INTEGER NOT NULL CHECK(level_no>0), kind TEXT NOT NULL DEFAULT 'play' CHECK(kind IN ('play','break')), small_blind INTEGER NOT NULL DEFAULT 0 CHECK(small_blind>=0), big_blind INTEGER NOT NULL DEFAULT 0 CHECK(big_blind>=0), ante INTEGER NOT NULL DEFAULT 0 CHECK(ante>=0), duration_seconds INTEGER NOT NULL CHECK(duration_seconds>0), PRIMARY KEY(tournament_id,level_no), CHECK(kind='break' OR big_blind>=small_blind));
CREATE TABLE tournament_clock (tournament_id TEXT PRIMARY KEY REFERENCES tournaments(id), level_no INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'stopped' CHECK(state IN ('stopped','running','paused','finished')), remaining_seconds INTEGER NOT NULL CHECK(remaining_seconds>=0), started_at_ms INTEGER, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE prize_allocations (tournament_id TEXT NOT NULL REFERENCES tournaments(id), place INTEGER NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), PRIMARY KEY(tournament_id,place), FOREIGN KEY(tournament_id,user_id) REFERENCES tournament_members(tournament_id,user_id));
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, tournament_id TEXT REFERENCES tournaments(id), actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE idempotency_keys (scope TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(scope,key));
CREATE TABLE outbox_events (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL REFERENCES tournaments(id), event_type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TEXT);
CREATE INDEX idx_entries_tournament_user ON entries(tournament_id,user_id,status);
CREATE INDEX idx_payments_tournament_user ON payments(tournament_id,user_id,status);
CREATE INDEX idx_outbox_unpublished ON outbox_events(published_at,created_at);
